function token($oid,$exp){global $c;$p=base64url(json_encode(['o'=>$oid,'e'=>$exp]));return $p.'.'.base64url(hash_hmac('sha256',$p,$c['secret'],true));}
function base64url($s){return rtrim(strtr(base64_encode($s),'+/','-_'),'=');}
function auth(){global $c;$t=$_SERVER['HTTP_X_AUTH_TOKEN']??'';$x=explode('.',$t);if(count($x)!==2)out(['error'=>'登录已失效，请重新登录'],401);$p=json_decode(base64_decode(strtr($x[0],'-_','+/')),true);if(!$p||($p['e']??0)<time()||!hash_equals($x[1],base64url(hash_hmac('sha256',$x[0],$c['secret'],true))))out(['error'=>'登录已失效，请重新登录'],401);return $p['o'];}
